```python
import math

# Updated function to generate n fibonacci series numbers with error handling for invalid inputs
def fibonacci_sequence(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")

    fibonacci = [0, 1]
    while len(fibonacci) < n:
        fibonacci.append(fibonacci[-1] + fibonacci[-2])

    return fibonacci[:n]

# Updated function to check if a number is in the fibonacci series with error handling for invalid inputs
def is_fibonacci(num):
    if not isinstance(num, int) or num < 0:
        raise ValueError("Input must be a non-negative integer.")

    x = 5 * num**2
    return math.isqrt(x + 4) ** 2 == x + 4 or math.isqrt(x - 4) ** 2 == x - 4

# Test these functions with invalid inputs
try:
    print(fibonacci_sequence('100'))
except Exception as e:
    print(str(e))

try:
    print(is_fibonacci(-5))
except Exception as e:
    print(str(e))
