use anyhow::{anyhow, Context, Result as ResultType};
use cpal::traits::{DeviceTrait, HostTrait};

#[cfg(not(windows))]
fn get_device() -> ResultType<(cpal::Device, cpal::SupportedStreamConfig)> {
    let host = cpal::default_host();
    let default_device = host.default_output_device().ok_or_else(|| anyhow!("No output device available"))?;
    let format = default_device.default_output_config()
        .map_err(|e| anyhow!(e))
        .with_context(|| "Failed to get default output format")?;
    Ok((default_device, format))
}

#[cfg(windows)]
fn get_device() -> ResultType<(cpal::Device, cpal::SupportedStreamConfig)> {
    // Windows-specific implementation to retrieve default output device and format
    unimplemented!()
}

fn main() {
    match get_device() {
        Ok((device, format)) => {
            log::info!("Default output device: {}", device.name().unwrap_or("".to_owned()));
            log::info!("Default output format: {:?}", format);
        }
        Err(e) => {
            log::error!("Error: {}", e);
        }
    }
}
```

