class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

    def insert(self, data):
        if data < self.data:
            if self.left is None:
                self.left = Node(data)
            else:
                self.left.insert(data)
        elif data > self.data:
            if self.right is None:
                self.right = Node(data)
            else:
                self.right.insert(data)

    def search(self, data):
        if data < self.data:
            if self.left is None:
                return False
            return self.left.search(data)
        elif data > self.data:
            if self.right is None:
                return False
            return self.right.search(data)
        else:
            return True

    def compare(self, Node2):
        if self.data is None and Node2.data is None:
            return 0
        if (self.data is not None and Node2.data is None) or (self.data is None and Node2.data is not None):
            return False
        if self.data == Node2.data:
            return 0
        elif self.data < Node2.data:
            return -1
        else:
            return 1
```

