You should implement the `DirectedGraph` class and its methods to find the shortest path between two nodes.

```java
import java.util.*;

class DirectedGraph {
    Map<String, Node> nodes;

    public DirectedGraph() {
        this.nodes = new HashMap<>();
    }

    public void addNode(Node node) {
        nodes.put(node.id, node);
    }

    public void addEdge(Node source, Node destination, int weight) {
        source.edges.add(new Edge(destination, weight));
    }

    public List<Node> shortestPath(Node start, Node end) {
        Map<Node, Integer> distance = new HashMap<>();
        Map<Node, Node> previous = new HashMap<>();
        PriorityQueue<Node> queue = new PriorityQueue<>(Comparator.comparingInt(distance::get));

        for (Node node : nodes.values()) {
            distance.put(node, node == start ? 0 : Integer.MAX_VALUE);
            queue.add(node);
        }

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            if (current == end) {
                List<Node> path = new ArrayList<>();
                while (previous.containsKey(current)) {
                    path.add(0, current);
                    current = previous.get(current);
                }
                path.add(0, start);
                return path;
            }

            for (Edge edge : current.edges) {
                int alt = distance.get(current) + edge.weight;
                if (alt < distance.get(edge.destination)) {
                    distance.put(edge.destination, alt);
                    previous.put(edge.destination, current);
                    queue.remove(edge.destination);
                    queue.add(edge.destination);
                }
            }
        }

        return new ArrayList<>(); // No path found
    }
}
```

