import Foundation

func convertToSwiftDictionary(_ pythonDict: [String: Any]) -> [String: Any] {
    var swiftDict: [String: Any] = [:]

    let vowelLetters: Set<Character> = ["a", "e", "i", "o", "u"]

    for (key, value) in pythonDict {
        guard let firstCharacter = key.first else { continue }

        if vowelLetters.contains(firstCharacter) {
            if let intValue = value as? Int {
                swiftDict[key] = intValue
            } else if let intListValue = value as? [Int] {
                swiftDict[key] = intListValue.sorted()
            }
        }
    }

    return swiftDict
}

