```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;
    struct Node* next;
};

// Function to insert a new node at the beginning of the list
void insertNode(struct Node** head, int value) {
    // Create a new node
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;

    // If the list is empty, make the new node as the head
    if (*head == NULL) {
        *head = newNode;
    } 
    // Otherwise, add the new node at the beginning
    else {
        newNode->next = *head;
        *head = newNode;
    }
}

// Function to delete a node with a given value from the list
void deleteNode(struct Node** head, int value) {
    // If the list is empty, return
    if (*head == NULL) {
        return;
    }

    // If the node to be deleted is the head, update the head
    if ((*head)->data == value) {
        struct Node* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }

    // Search for the node to be deleted
    struct Node* current = *head;
    struct Node* prev = NULL;
    while (current != NULL && current->data != value) {
        prev = current;
        current = current->next;
    }

    // If the node was not found, return
    if (current == NULL) {
        return;
    }

    // Delete the node
    prev->next = current->next;
    free(current);
}

// Function to search for a node with a given value in the list
struct Node* searchNode(struct Node* head, int value) {
    struct Node* current = head;
    while (current != NULL) {
        if (current->data == value) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to print all the elements of the list
void printList(struct Node* head) {
    struct Node* current = head;
    while (current != NULL) {
        printf("%d ", current->data);
        current = current->next;
    }
    printf("\n");
}

// Function to reverse the linked list
void reverseList(struct Node** head) {
    struct Node* prev = NULL;
    struct Node* current = *head;
    struct Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    *head = prev;
}

int main() {
    struct Node* head = NULL;

    // Insert nodes at the beginning of the list
    insertNode(&head, 5);
    insertNode(&head, 4);
    insertNode(&head, 3);
    insertNode(&head, 2);
    insertNode(&head, 1);

    // Print all the elements of the list
    printf("Original List: ");
    printList(head);

    // Delete a node with a given value from the list
    deleteNode(&head, 3);
    deleteNode(&head, 1);

    // Print all the elements of the list after deletion
    printf("List after Deletion: ");
    printList(head);

    // Search for a node with a given value in the list
    struct Node* foundNode = searchNode(head, 4);
    if (foundNode != NULL) {
        printf("Node found: %d\n", foundNode->data);
    } else {
        printf("Node not found\n");
    }

    // Reverse the linked list
    reverseList(&head);

    // Print all the elements of the reversed list
    printf("Reversed List: ");
    printList(head);

    return 0;
}
