        if (grades.length == 0) {
            return 0;
        }

        int sum = 0;
        int minGrade = grades[0];
        int maxGrade = grades[0];

        for (int grade : grades) {
            sum += grade;

            if (grade < minGrade) {
                minGrade = grade;
            }

            if (grade > maxGrade) {
                maxGrade = grade;
            }
        }

        sum -= minGrade;
        sum -= maxGrade;

        return (double) sum / (grades.length - 2);
    }

    public int[] getTopThreeGrades() {
        int[] topThreeGrades = new int[3];

        if (grades.length < 3) {
            System.arraycopy(grades, 0, topThreeGrades, 0, grades.length);
            Arrays.sort(topThreeGrades);
        } else {
            int[] sortedGrades = Arrays.copyOf(grades, grades.length);
            Arrays.sort(sortedGrades);
            System.arraycopy(sortedGrades, sortedGrades.length - 3, topThreeGrades, 0, 3);
        }

        return topThreeGrades;
    }

    public int[] mergeSort() {
        return mergeSort(grades);
    }

    private int[] mergeSort(int[] array) {
        if (array.length <= 1) {
            return array;
        }

        int mid = array.length / 2;
        int[] left = Arrays.copyOfRange(array, 0, mid);
        int[] right = Arrays.copyOfRange(array, mid, array.length);

        left = mergeSort(left);
        right = mergeSort(right);

        return merge(left, right);
    }

    private int[] merge(int[] left, int[] right) {
        int[] merged = new int[left.length + right.length];
        int i = 0;
        int j = 0;
        int k = 0;

        while (i < left.length && j < right.length) {
            if (left[i] < right[j]) {
                merged[k++] = left[i++];
            } else {
                merged[k++] = right[j++];
            }
        }

        while (i < left.length) {
            merged[k++] = left[i++];
        }

        while (j < right.length) {
            merged[k++] = right[j++];
        }

        return merged;
    }

