        for (int grade : grades) {
            int count = gradeCount.getOrDefault(grade, 0) + 1;
            gradeCount.put(grade, count);

            if (count > maxCount || (count == maxCount && grade < mode)) {
                mode = grade;
                maxCount = count;
            }
