import java.util.*;

public class Main {

    private static int m;
    private static int n;
    private static int[][][] dp;

    private int DFS(int[][] grid, int x, int y, int k) {

        if (k == 0) return 0;
        if (dp[x][y][k] != -1) return dp[x][y][k];

        int temp = Integer.MIN_VALUE;
        int[][] dir = {{0, -1}, {0, 1}, {1, 0}, {-1, 0}};

        for(int i = 0; i < dir.length; i++){
            int dx = x + dir[i][0];
            int dy = y + dir[i][1];

            if(dx >= 0 && dx < m && dy >= 0 && dy < n){
                temp = Math.max(temp, DFS(grid, dx, dy, k - 1));
            }
        }

        dp[x][y][k] = temp + grid[x][y];

        return dp[x][y][k];
    }

    private List<Integer> maxSumPath(int[][] grid, int k) {

        if (grid == null || grid.length == 0 || k <= 0 || k > grid.length * grid[0].length){
            throw new IllegalArgumentException("Invalid Input");
        }

        m = grid.length;
        n = grid[0].length;

