```go
package main

import (
	"fmt"
	"math"
	"sync"
)

func main() {
	primeChannel := make(chan int)
	done := make(chan bool)
	wg := &sync.WaitGroup{}

	// Start 10 goroutines to generate prime numbers concurrently
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go generatePrimes(primeChannel, done, wg)
	}

	go func() {
		// Print the first 1000 prime numbers
		count := 0
		for prime := range primeChannel {
			fmt.Println(prime)
			count++
			if count == 1000 {
				break
			}
		}

		// Signal that we are done printing prime numbers
		done <- true
	}()

	// Wait for all the goroutines to finish
	wg.Wait()

	// Close the prime channel
	close(primeChannel)

	// Wait for the printing goroutine to finish
	<-done
}

func generatePrimes(primeChannel chan<- int, done <-chan bool, wg *sync.WaitGroup) {
	defer wg.Done()
	primes := []int{2, 3}
	num := 5

	for {
		select {
		case <-done:
			return
		default:
			if isPrime(num, primes) {
				primeChannel <- num
			}
			num += 2
		}
	}
}

func isPrime(num int, primes []int) bool {
	max := int(math.Sqrt(float64(num)))

	for _, prime := range primes {
		if prime > max {
			break
		}
		if num%prime == 0 {
			return false
		}
	}

	return true
}
