```python
from typing import List, Dict, Any
import re
import codecs

class VersionControlSystem:
    def __init__(self):
        pass

    def compute_delta(self, rule_path: str, mode: str, src_paths: List[str]) -> Dict[str, Any]:
        try:
            rules = self.load_rules(rule_path)
        except FileNotFoundError:
            return {"error": f"Rule file '{rule_path}' not found."}

        delta_info = {}
        for src_path in src_paths:
            try:
                delta_info[src_path] = self.compute_file_delta(src_path, rules, mode)
            except FileNotFoundError:
                delta_info[src_path] = f"Source file '{src_path}' not found."

        return {
            "rule_path": rule_path,
            "mode": mode,
            "source_paths": src_paths,
            "delta_info": delta_info
        }

    def load_rules(self, rule_path: str) -> Dict[str, Any]:
        with codecs.open(rule_path, "r", encoding='utf-8', errors='ignore') as file:
            rules = file.readlines()

        rules = {re.compile(parts[0].strip()): parts[1].strip() for rule in rules 
                 if (parts := rule.split(":")) and not rule.startswith("#")}

        return rules

    def compute_file_delta(self, src_path: str, rules: Dict[str, str], mode: str) -> List[str]:
        with codecs.open(src_path, "r", encoding='utf-8', errors='ignore') as file:
            source_lines = file.readlines()

        delta = []
        for pattern, action in rules.items():
            for line_num, line in enumerate(source_lines, start=1):
                if pattern.search(line):
                    delta.append(f"{action.capitalize()} line {line_num}: {line.strip()}")
                    break

        return delta
```
In the `load_rules` method, the rules dictionary is built with regular expression patterns as keys and actions as values. 

In the `compute_file_delta` method, the for-loop now goes over the items of the rules dictionary. For each source line that matches the pattern, the corresponding action is carried out and the detail is recorded in the delta list.

Note: This new approach assumes that each rule in the rules file is written in the format "pattern:action", where "pattern" is the regular expression pattern and "action" is the action to be performed.

