```python
def single_pass_replace(text_string, replacements):
    words = text_string.split()
    counts = {}

    for i, word in enumerate(words):
        lowercase_word = word.lower()

        for target, (replacement, n) in replacements.items():
            counts.setdefault(target, 0)

            if lowercase_word == target:
                counts[target] += 1

                if counts[target] == n:
                    # Perform replacement, preserving case of the original word
                    if word.istitle():
                        words[i] = replacement.title()
                    elif word.isupper():
                        words[i] = replacement.upper()
                    else:
                        words[i] = replacement
                    counts[target] = 0

    return " ".join(words)
```

